// The browser-side entry point to Soom's Rust engine.
//
// `pkg/` is generated by `pnpm wasm` (wasm-pack). Nothing in here contains
// pattern logic: it loads the module and gives the app typed access to it.

import init, { engineVersion } from '../pkg/soom_wasm_core.js'

let ready: Promise<void> | undefined

/** Loads and instantiates the WebAssembly engine. Safe to call repeatedly. */
export function loadEngine(): Promise<void> {
  ready ??= init().then(() => undefined)
  return ready
}

export { engineVersion }
